import React, { useState, useEffect } from 'react';
import { Table, Button, Modal, ModalHeader, ModalBody, ModalFooter, Form, FormGroup, Label, Input } from 'reactstrap';
import { FaEdit, FaTrash, FaPlus, FaSearch, FaFileExport } from 'react-icons/fa';
import axios from 'axios';
import { toast } from 'react-toastify';
import CusSwal from '../../../Utils/CustomSwal/CusSwal';
import { BASE_URL } from '../../../Utils/config';
import {message} from 'antd'
import PdfGenerator from '../../../Utils/Pdfs/SupplierPDF';

const InventoryDetails = () => {
  const [inventory, setInventory] = useState([]);
  const [filteredInventory, setFilteredInventory] = useState([]);
  const [modal, setModal] = useState(false);
  const [currentItem, setCurrentItem] = useState({
    name: '',
    quantity: '',
    price: '',
    category: '',
    supplier: '',
  });
  const [isEditing, setIsEditing] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    fetchInventory();
  }, []);

  useEffect(() => {
    setFilteredInventory(
      inventory.filter(item =>
        Object.values(item).some(value =>
          value.toString().toLowerCase().includes(searchTerm.toLowerCase())
        )
      )
    );
  }, [searchTerm, inventory]);

  const fetchInventory = async () => {
    try {
      const response = await axios.get(`${BASE_URL}/inventory`);
      setInventory(response.data);
      setFilteredInventory(response.data);
    } catch (error) {
      toast.error('Failed to fetch inventory');
    }
  };

  const toggle = () => setModal(!modal);

  const handleInputChange = (e) => {
    setCurrentItem({ ...currentItem, [e.target.name]: e.target.value });
  };

  const handleSearch = (e) => {
    setSearchTerm(e.target.value);
  };

  const handleAddItem = async () => {
    try {
      await axios.post(`${BASE_URL}/inventory`, currentItem);
      fetchInventory();
      toggle();
      message.success("Item added successfully")
    } catch (error) {
      toast.error('Failed to add item');
    }
  };

  const handleUpdateItem = async () => {
    try {
      await axios.post(`${BASE_URL}/inventory/${currentItem._id}`, currentItem);
      fetchInventory();
      toggle();
      message.success("Item updated successfully")
    } catch (error) {
      toast.error('Failed to update item');
    }
  };

  const handleDeleteItem = async (id) => {
    CusSwal.deleteConfiramation(async () => {
      try {
        await axios.delete(`${BASE_URL}/inventory/${id}`);
        fetchInventory();
        message.success("Item deleted successfully")
      } catch (error) {
        toast.error('Failed to delete item');
      }
    });
  };

  const openUpdateModal = (item) => {
    setCurrentItem(item);
    setIsEditing(true);
    toggle();
  };

  const handleExportPDF = () => {
    const headers = ['Name', 'Quantity', 'Price', 'Category', 'Supplier'];
    const data = filteredInventory.map(item => [
      item.name,
      item.quantity,
      item.type,
      item.brand,
      item.price
    ]);
    const title = 'Inventory Details';
    const generatedDate = new Date().toLocaleString();
    const numberOfItems = filteredInventory.length;

    PdfGenerator.generatePdf(data, title, headers, numberOfItems, generatedDate);
  };

  return (
    <div className="container mt-5">
      <h2 className="mb-4">Inventory Details</h2>
      <div className="d-flex justify-content-between mb-3">
        <Button size='sm'  style={{backgroundColor: 'rgb(1, 126, 175)', borderColor: 'rgb(1, 126, 175)'}} onClick={() => { setIsEditing(false); setCurrentItem({}); toggle(); }}>
          <FaPlus /> Add New Item
        </Button>
        <div className="d-flex">
          <Input
            type="text"
            placeholder="Search inventory..."
            value={searchTerm}
            onChange={handleSearch}
            className="mr-2"
          />
          <Button color="success" size='sm' onClick={handleExportPDF}>
            <FaFileExport /> Export PDF
          </Button>
        </div>
      </div>
      <Table striped bordered hover responsive>
        <thead>
          <tr>
            <th>Name</th>
            <th>Quantity</th>
            <th>Type</th>
            <th>Brand</th>
            <th>Price</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {filteredInventory.map((item) => (
            <tr key={item._id}>
              <td>{item.name}</td>
              <td>{item.quantity}</td>
              <td>{item.type}</td>
              <td>{item.brand}</td>
              <td>{item.price}</td>
              <td>
                <Button color="warning"  style={{marginRight: '5px'}} onClick={() => openUpdateModal(item)} className="mr-2">
                  <FaEdit /> Update
                </Button>
                <Button  style={{backgroundColor: 'red', borderColor: 'red', marginLeft: '5px'}} onClick={() => handleDeleteItem(item._id)} className="mr-2">
                  <FaTrash /> Delete
                </Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>

      <Modal isOpen={modal} toggle={toggle}>
        <ModalHeader toggle={toggle}>{isEditing ? 'Update Item' : 'Add New Item'}</ModalHeader>
        <ModalBody>
        <Form>
            <FormGroup>
              <Label for="name">Item Name</Label>
              <Input type="text" name="name" id="name" value={currentItem.name || ''} onChange={handleInputChange} />
            </FormGroup>
            <FormGroup>
              <Label for="category">Item type</Label>
              <Input type="select" name="type" id="type" value={currentItem.type || ''} onChange={handleInputChange}>
                <option value="">Select a category</option>
                <option value="parts">Parts</option>
                <option value="tools">Tools</option>
                <option value="lubricants">Lubricants</option>
                <option value="tires">Tires</option>
              </Input>
            </FormGroup>
            <FormGroup>
              <Label for="quantity">Item Quantity</Label>
              <Input type="number" name="quantity" id="quantity" value={currentItem.quantity || ''} onChange={handleInputChange} />
            </FormGroup>
            <FormGroup>
              <Label for="price">Item Price</Label>
              <Input type="number" name="price" id="price" value={currentItem.price || ''} onChange={handleInputChange} />
            </FormGroup>
            <FormGroup>
              <Label for="supplier">Item Brand</Label>
              <Input type="text" name="brand" id="brand" value={currentItem.brand || ''} onChange={handleInputChange} />
            </FormGroup>
          </Form>
        </ModalBody>
        <ModalFooter>
          <Button color="primary" onClick={isEditing ? handleUpdateItem : handleAddItem}>
            {isEditing ? 'Update' : 'Add'}
          </Button>
          <Button color="secondary" onClick={toggle}>Cancel</Button>
        </ModalFooter>
      </Modal>
    </div>
  );
};

export default InventoryDetails;
