  import React, { useState, useEffect, useContext } from 'react';
  import { Container, Row, Col, Form, Button } from 'react-bootstrap';
  import DatePicker from 'react-datepicker';
  import 'react-datepicker/dist/react-datepicker.css';
  import axios from 'axios';
  import { BASE_URL } from '../Utils/config';
  import { toast } from 'react-toastify';
  import { AuthContext } from '../context/AuthContext';

  const Contact = () => {
    const { user } = useContext(AuthContext);
    const [carType, setCarType] = useState('');
    const [serviceDate, setServiceDate] = useState(new Date());
    const [message, setMessage] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [feedbacks, setFeedbacks] = useState([]);

    const handleSubmit = async (e) => {
      e.preventDefault();
      setIsSubmitting(true);
      try {
        // Prepare the review data to be sent
        const reviewData = {
          user: user._id,
          name: user.username,
          email: user.email,
          carType,
          serviceDate: serviceDate.toISOString(), // Ensure proper date format
          message
        };
    
        console.log('Submitting review data:', reviewData);
    
        // Make the POST request to the backend
        const response = await axios.post(`${BASE_URL}/review`, reviewData, {
          headers: {
            'Content-Type': 'application/json' // Ensure the correct content type
          }
        });
    
        // Log the response to verify if it was saved successfully
        console.log('Review saved:', response.data);
    
        // Reset the form fields after successful submission
        setCarType('');
        setServiceDate(new Date());
        setMessage('');
    
        // Display success notification
        toast.success('Review submitted successfully!');
      } catch (error) {
        console.error('Error saving review:', error);
        if (error.response) {
          console.error('Server response:', error.response.data);
        }
        toast.error('Error submitting review. Check whether you are logged in.');
      } finally {
        // Reset the submitting state
        setIsSubmitting(false);
      }
    };
    

    return (
      <Container className="contact-container my-5">
        <Row>
          <Col md={4} className="contact-info">
            <h2>Contact Us</h2>
            <div className="contact-item">
              <span>+1 (123) 456-7890</span>
            </div>
            <div className="contact-item">
              <span>info@autoservice.com</span>
            </div>
            <div className="contact-item">
              <span>123 Auto Street, Car City, ST 12345</span>
            </div>
          </Col>
          <Col md={8} className="contact-form"  style={{ backgroundColor: '#e6f7ff' }}>
            <h2>Leave a Review</h2>
            <Form onSubmit={handleSubmit}>
              <Form.Group controlId="name">
                <Form.Label>Name</Form.Label>
                <Form.Control
                  type="text"
                  placeholder="Enter your name"
                  value={user?.username || ''}
                  disabled
                />
              </Form.Group>
              <Form.Group controlId="email">
                <Form.Label>Email</Form.Label>
                <Form.Control
                  type="email"
                  placeholder="Enter your email"
                  value={user?.email || ''}
                  disabled
                />
              </Form.Group>
              <Form.Group controlId="carType">
                <Form.Label>Car Type</Form.Label>
                <Form.Control
                  as="select"
                  value={carType}
                  onChange={(e) => setCarType(e.target.value)}
                  required
                >
                  <option value="" disabled>Select car type</option>
                  <option value="car">Car</option>
                  <option value="van">Van</option>
                  <option value="bus">Bus</option>
                  <option value="lorry">Lorry</option>
                  <option value="motorcycle">Motorcycle</option>
                </Form.Control>
              </Form.Group>
              <Form.Group controlId="Date">
                <Form.Label>Date</Form.Label><br/>
                <DatePicker
                  selected={serviceDate}
                  onChange={(date) => setServiceDate(date)}
                  className="form-control"
                  dateFormat="MMMM d, yyyy"
                  required
                />
              </Form.Group>
              <Form.Group controlId="message">
                <Form.Label>Message</Form.Label>
                <Form.Control
                  as="textarea"
                  rows={3}
                  placeholder="Enter your message"
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                  required
                />
              </Form.Group>
              <Button variant="primary" type="submit" className="mt-3" disabled={isSubmitting}>
                {isSubmitting ? 'Submitting...' : 'Submit Review'}
              </Button>
            </Form>
          </Col>
        </Row>
      </Container>
    );
  };

  export default Contact;