import React, { useState, useEffect } from 'react';
import { Table, Button, Modal, ModalHeader, ModalBody, ModalFooter, Form, FormGroup, Label, Input } from 'reactstrap';
import { FaEdit, FaTrash, FaPlus, FaSearch, FaFileExport } from 'react-icons/fa';
import axios from 'axios';
import { toast } from 'react-toastify';
import CusSwal from '../../../Utils/CustomSwal/CusSwal';
import { BASE_URL } from '../../../Utils/config';
import {message} from 'antd'
import PdfGenerator from '../../../Utils/Pdfs/SupplierPDF'

const SupplierDetails = () => {
  const [suppliers, setSuppliers] = useState([]);
  const [filteredSuppliers, setFilteredSuppliers] = useState([]);
  const [modal, setModal] = useState(false);
  const [currentSupplier, setCurrentSupplier] = useState({
    name: '',
    email: '',
    phone: '',
    type: '',
    city: '',
  });
  const [isEditing, setIsEditing] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    fetchSuppliers();
  }, []);

  useEffect(() => {
    setFilteredSuppliers(
      suppliers.filter(supplier =>
        Object.values(supplier).some(value =>
          value.toString().toLowerCase().includes(searchTerm.toLowerCase())
        )
      )
    );
  }, [searchTerm, suppliers]);

  const fetchSuppliers = async () => {
    try {
      const response = await axios.get(`${BASE_URL}/supplier`);
      setSuppliers(response.data);
      setFilteredSuppliers(response.data);
    } catch (error) {
      toast.error('Failed to fetch suppliers');
    }
  };

  const toggle = () => setModal(!modal);

  const handleInputChange = (e) => {
    setCurrentSupplier({ ...currentSupplier, [e.target.name]: e.target.value });
  };

  const handleSearch = (e) => {
    setSearchTerm(e.target.value);
  };

  const handleAddSupplier = async () => {
    try {
      await axios.post(`${BASE_URL}/supplier`, currentSupplier);
      fetchSuppliers();
      toggle();
      message.success("Supplier added successfully")
    } catch (error) {
      toast.error('Failed to add supplier');
    }
  };

  const handleUpdateSupplier = async () => {
    try {
      await axios.post(`${BASE_URL}/supplier/${currentSupplier._id}`, currentSupplier);
      fetchSuppliers();
      toggle();
      message.success("Supplier updated successfully")
    } catch (error) {
      toast.error('Failed to update supplier');
    }
  };

  const handleDeleteSupplier = async (id) => {
    CusSwal.deleteConfiramation(async () => {
      try {
        await axios.delete(`${BASE_URL}/supplier/${id}`);
        fetchSuppliers();
        message.success("Supplier deleted successfully")
      } catch (error) {
        toast.error('Failed to delete supplier');
      }
    });
  };

  const openUpdateModal = (supplier) => {
    setCurrentSupplier(supplier);
    setIsEditing(true);
    toggle();
  };

  
const handleExportPDF = () => {
  const headers = ['Name', 'Email', 'City', 'Type', 'Contact'];
  const data = filteredSuppliers.map(supplier => [
    supplier.name,
    supplier.email,
    supplier.city,
    supplier.type,
    supplier.contact
  ]);
  
  const title = 'Supplier Details';
  const generatedDate = new Date().toLocaleString();
  const numberOfItems = filteredSuppliers.length;

  PdfGenerator.generatePdf(data, title, headers, numberOfItems, generatedDate);
};

  return (
    <div className="container mt-5">
      <h2 className="mb-4">Supplier Details</h2>
      <div className="d-flex justify-content-between mb-3">
        <Button size="sm" style={{backgroundColor: 'rgb(1, 126, 175)', borderColor: 'rgb(1, 126, 175)'}} onClick={() => { setIsEditing(false); setCurrentSupplier({}); toggle(); }}>
          <FaPlus /> Add New Supplier
        </Button>
        <div className="d-flex">
          <Input
            type="text"
            placeholder="Search suppliers..."
            value={searchTerm}
            onChange={handleSearch}
            className="mr-2"
            size="sm"
          />
          <Button color="success" size="sm" onClick={handleExportPDF}>
            <FaFileExport /> Export
          </Button>
        </div>
      </div>
      <Table striped bordered hover responsive>
        <thead>
          <tr>
            <th>Name</th>
            <th>Email</th>
            <th>City</th>
            <th>Type</th>
            <th>Contact</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {filteredSuppliers.map((supplier) => (
            <tr key={supplier._id}>
              <td>{supplier.name}</td>
              <td>{supplier.email}</td>
              <td>{supplier.city}</td>
              <td>{supplier.type}</td>
              <td>{supplier.contact}</td>
              <td>
                <Button color="warning" style={{marginRight: '5px'}} onClick={() => openUpdateModal(supplier)} className="mr-2">
                  <FaEdit /> Update
                </Button>
                <Button style={{backgroundColor: 'red', borderColor: 'red', marginLeft: '5px'}}onClick={() => handleDeleteSupplier(supplier._id)} className="mr-2">
                  <FaTrash /> Delete
                </Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>

      <Modal isOpen={modal} toggle={toggle}>
        <ModalHeader toggle={toggle}>{isEditing ? 'Update Supplier' : 'Add New Supplier'}</ModalHeader>
        <ModalBody>
          <Form>
            <FormGroup>
              <Label for="name">Name</Label>
              <Input type="text" name="name" id="name" value={currentSupplier.name || ''} onChange={handleInputChange} />
            </FormGroup>
            <FormGroup>
              <Label for="email">Email</Label>
              <Input type="email" name="email" id="email" value={currentSupplier.email || ''} onChange={handleInputChange} />
            </FormGroup>
            <FormGroup>
              <Label for="phone">Phone</Label>
              <Input type="tel" name="contact" id="contact" value={currentSupplier.contact || ''} onChange={handleInputChange} />
            </FormGroup>
            <FormGroup>
              <Label for="address">Address</Label>
              <Input type="textarea" name="city" id="city" value={currentSupplier.city || ''} onChange={handleInputChange} />
            </FormGroup>
            <FormGroup>
              <Label for="type">Supplier Type</Label>
              <Input type="select" name="type" id="type" value={currentSupplier.type || ''} onChange={handleInputChange}>
                <option value="">Select a type</option>
                <option value="parts">Parts Supplier</option>
                <option value="service">Service Provider</option>
                <option value="tires">Tire Supplier</option>
                <option value="fuel">Fuel Supplier</option>
                <option value="tools">Tools and Equipment Supplier</option>
                <option value="lubricants">Lubricants Supplier</option>
              </Input>
            </FormGroup>
          </Form>
        </ModalBody>
        <ModalFooter>
          <Button color="primary" onClick={isEditing ? handleUpdateSupplier : handleAddSupplier}>
            {isEditing ? 'Update' : 'Add'}
          </Button>
          <Button color="secondary" onClick={toggle}>Cancel</Button>
        </ModalFooter>
      </Modal>
    </div>
  );
};

export default SupplierDetails;