import React, { useEffect, useState, useContext } from 'react';
import Toaster from '../../../Utils/Toaster';
import { employeeHeader } from '../../../Utils/TableHeaders';
import CusSwal from '../../../Utils/CustomSwal/CusSwal';
import PdfGenerator from '../../../Utils/Pdfs/EmployeePDF';
import ResponseHandler from '../../../Utils/ResponseHandler';
import { useNavigate } from 'react-router-dom';
import { BASE_URL } from '../../../Utils/config';
import axios from 'axios';
import { Container, Row, Col, Form, Button, Card } from 'react-bootstrap';
import { toast } from 'react-toastify';
import { AuthContext } from '../../../context/AuthContext';

export default function EmployeeManage() {
  const { user, dispatch } = useContext(AuthContext);
  const [employees, setEmployees] = useState([]);
  const [filteredEmployees, setFilteredEmployees] = useState([]);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const [isEditing, setIsEditing] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`${BASE_URL}/employee`);
      setEmployees(response.data);
      setFilteredEmployees(response.data);
    } catch (error) {
      console.error('Error fetching Employees:', error);
      toast.error('Failed to load Employees');
    } finally {
      setLoading(false);
      Toaster.dismissLoadingToast();
    }
  };

  const generatePdf = () => {
    Toaster.loadingToast('Generating Pdf');
    try {
      console.log(employees);
      PdfGenerator.generatePdf(employees, "Employees List", employeeHeader);
      Toaster.justToast('success', 'Creating The Pdf For You', () => {});
    } catch (error) {
      Toaster.justToast('error', 'Generation failed', () => {});
    } finally {
      Toaster.dismissLoadingToast();
    }
  };

  const handleSearch = (e) => {
    const query = e.target.value.toLowerCase();
    setSearchQuery(query);
    const filteredEmployees = employees.filter((employee) =>
      employee.type.toLowerCase().includes(query)
    );
    setFilteredEmployees(filteredEmployees);
  };

  const handleEmployeeEdit = (employee) => {
    console.log(employee._id);
    navigate(`/admin/employees/edit/${employee._id}`);
    setIsEditing(true);
  };

  const handleDelete = async (employeeId) => {
    CusSwal.deleteConfiramation(async () => {
      try {
        console.log(employeeId);
        await axios.delete(`${BASE_URL}/employee/${employeeId}`);
        setEmployees(employees.filter(employee => employee._id !== employeeId));
        setFilteredEmployees(filteredEmployees.filter(employee => employee._id !== employeeId));
        Toaster.justToast('success', 'Employee deleted successfully');
      } catch (err) {
        console.error(err);
        Toaster.justToast('error', 'Failed to delete Employee');
      }
    });
  };

  return (
    <div className="body-wrapper">
      <div className="container-fluid">
        <div className="row">
          <div className="col-12 d-flex align-items-stretch">
            <div className="card w-100 shadow-sm">
            <div className='d-flex justify-content-end align-items-center mb-4'>
              
        <form className="position-relative">
                      <input
                          value={searchQuery}
                          onChange={handleSearch}
                          type="text" className="form-control search-chat py-2 ps-5" id="text-srh" placeholder="Search" />
                      <i className="ti ti-search position-absolute top-50 start-0 translate-middle-y fs-6 text-dark ms-3" />
                  </form>
              <button className='btn btn-outline-dark mx-2' onClick={generatePdf}>Export</button>
              <button className='btn text-white' style={{backgroundColor:'#1681e5'}} onClick={() => {
                  navigate(`/employeeAdd`);
              }}>Add New</button>
         </div>
              <div className="card-body p-4">
                <h3>All Employees</h3>
                <div className="table-responsive">
                  <table className="table table-striped table-hover">
                    <thead>
                      <tr>
                        <th>Name</th>
                        <th>Email</th>
                        <th>Type</th>
                        <th>Contact</th>
                        <th>Address</th>
                        <th>NIC</th>
                        <th>Age</th>
                        <th>Salary</th>
                        <th>Attendance</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                    {filteredEmployees && filteredEmployees.length > 0 ? (
                      filteredEmployees.map((employee) => (
                        <tr key={employee.id}>
                          <td>{employee.name}</td>
                          <td>{employee.email}</td>
                          <td>{employee.type}</td>
                          <td>{employee.contact}</td>
                          <td>{employee.address}</td>
                          <td>{employee.nic}</td>
                          <td>{employee.age}</td>
                          <td>{employee.salary}</td>
                          <td>{employee.attendance}</td>
                          <td>
                            <button
                              className="btn btn-primary"
                              onClick={() => handleEmployeeEdit(employee, employee._id)}
                            >
                              Update
                            </button>
                            <button
                              className="btn btn-danger"
                              onClick={() => handleDelete(employee._id)}
                            >
                              Delete
                            </button>
                          </td>
                        </tr>
                      ))) : (
                        <tr>
                          <td colSpan={6}>No Employee found.</td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}